    adcs_vec3_t u, c1, c2, c3, tmp, result;
    double ca, sa, one_minus_ca, u_dot_v;

    if ((vector == NULL) || (axis == NULL) || (rotated == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(vector)) || (!isfinite(angle_rad))) {
        *rotated = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    if ((adcs_vec3_normalize(axis, ADCS_EPS_NORM, &u) != ADCS_OK) || (!adcs_is_finite_vec3(&u))) {
        *rotated = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    ca = cos(angle_rad);
    sa = sin(angle_rad);
    one_minus_ca = 1.0 - ca;
    u_dot_v = adcs_vec3_dot(&u, vector);

    c1 = adcs_vec3_scale(vector, ca);
    tmp = adcs_vec3_cross(&u, vector);
    c2 = adcs_vec3_scale(&tmp, sa);
    c3 = adcs_vec3_scale(&u, u_dot_v * one_minus_ca);

    result = adcs_vec3_add(&c1, &c2);
    result = adcs_vec3_add(&result, &c3);

    if (!adcs_is_finite_vec3(&result)) {
        *rotated = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    *rotated = result;
    return ADCS_OK;
}

