adcs_status_t status;
adcs_vec3_t u, cv, uv_s, u_dot, result;
double c, s, dot;

if ((vector == NULL) || (axis == NULL) || (rotated == NULL)) {
    if (rotated != NULL) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
    }
    return ADCS_E_NULL;
}

if ((!adcs_is_finite_vec3(vector)) || (!adcs_is_finite_vec3(axis)) || (!isfinite(angle_rad))) {
    rotated->x = 0.0;
    rotated->y = 0.0;
    rotated->z = 0.0;
    return ADCS_E_RANGE;
}

status = adcs_vec3_normalize(axis, ADCS_EPS_NORM, &u);
if (status != ADCS_OK) {
    rotated->x = 0.0;
    rotated->y = 0.0;
    rotated->z = 0.0;
    return ADCS_E_RANGE;
}

c = cos(angle_rad);
s = sin(angle_rad);
dot = adcs_vec3_dot(&u, vector);

cv = adcs_vec3_scale(vector, c);
{
    adcs_vec3_t cross = adcs_vec3_cross(&u, vector);
    uv_s = adcs_vec3_scale(&cross, s);
}
u_dot = adcs_vec3_scale(&u, dot * (1.0 - c));

result = adcs_vec3_add(&cv, &uv_s);
result = adcs_vec3_add(&result, &u_dot);

*rotated = result;
return ADCS_OK;
}

